new_src='''from collections import Counter


def _components(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack, cells = [(r, c)], []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            comps.append((color, cells))
    return bg, comps


def _border_l(cells, h, w):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    if not ((r0 == 0 or r1 == h-1) and (c0 == 0 or c1 == w-1)):
        return None
    s = set(cells)
    for er, ec in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
        expected = {(er,c) for c in range(c0,c1+1)} | {(r,ec) for r in range(r0,r1+1)}
        if s == expected:
            return er, ec
    return None


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg, comps = _components(g)
    marker = None
    for color, cells in comps:
        elbow = _border_l(cells, h, w)
        if elbow is not None:
            marker = (color, cells, elbow)
            break
    if marker is None:
        return g
    key_color, key_cells, (er, ec) = marker
    groups = Counter()
    for color, cells in comps:
        if color != key_color:
            groups[color] += len(cells)
    if not groups:
        return g
    target_color = groups.most_common(1)[0][0]
    sr = 1 if er == min(r for r,c in key_cells) else -1
    sc = 1 if ec == min(c for r,c in key_cells) else -1
    candidates = []
    for color, cells in comps:
        if color != target_color:
            continue
        cr = sum(r for r,c in cells) / len(cells)
        cc = sum(c for r,c in cells) / len(cells)
        if (cr-er)*sr <= 0 and (cc-ec)*sc <= 0:
            candidates.append(((cr-er)**2 + (cc-ec)**2, cells))
    if candidates:
        cells = min(candidates, key=lambda x: x[0])[1]
        for r, c in cells:
            g[r][c] = key_color
    return g
'''
